int ao_manifest_checked(const uint8_t*m,unsigned role){return m&& !memcmp(m,"AUMFW1\0\0",8)&&u16(m+8)==1&&u16(m+10)==1&&m[12]==role&&m[13]<=3&&u16(m+14)==1&&u32(m+16)>=580&&u32(m+16)<=AO_SLOT_BYTES&&u64(m+20)>0&&u64(m+20)<=9007199254740991ULL&&u64(m+28)>0&&u64(m+28)<=9007199254740991ULL&&u16(m+36)==1&&(u16(m+38)&~1u)==0&&(m[13]>=2||u16(m+38)==0)&&!zero(m+40,32)&&!zero(m+72,20)&&!memcmp(m+92,key_id,32)&&string(m+124,32,0)&&string(m+156,128,1)&&string(m+284,64,0)&&!memcmp(m+348,board_profile,32)&&!memcmp(m+380,"AU",2)&&m[382]==24&&!m[383];}
