int ao_initialize(struct ao_context*c,const struct ao_port*p,const uint8_t*n,const uint8_t*g,uint64_t e,const uint8_t*o,const uint8_t*r,const uint8_t*boot,unsigned role){if(!c||!p||!n||!g||!o||!r||!boot||!e||zero(n,16)||zero(g,16)||zero(o,32)||zero(r,16)||zero(boot,16)||(role!=1&&role!=2)||!p->current||!p->now||!p->generation||!p->hash||!p->owner_verify||!p->publisher_verify||!p->sign||!p->random||!p->ephemeral||!p->derive||!p->gcm||!p->begin||!p->write||!p->finish||!p->abort||!p->activate||!p->confirm||!p->status)return 0;memset(c,0,sizeof *c);c->port=*p;memcpy(c->node,n,16);memcpy(c->group,g,16);memcpy(c->owner,o,32);memcpy(c->relay,r,16);memcpy(c->run,boot,16);c->epoch=e;c->role=(uint8_t)role;c->initialized=1;c->authority_generation=p->generation(p->context);return c->authority_generation!=0;}
