static int common(struct ao_context*c,const uint8_t*b){return !memcmp(b+16,c->node,16)&&!memcmp(b+32,c->group,16)&&u64(b+48)==c->epoch&&!memcmp(b+56,c->owner,32)&&!memcmp(b+88,c->relay,16)&&!zero(b+104,32);}
