static void abort_session(struct ao_context*c){if(c->state==AO_UPLOADING||c->state==AO_VERIFIED)c->port.abort(c->port.context);memset(c->keys,0,sizeof c->keys);memset(c->chunks,0,sizeof c->chunks);c->state=AO_IDLE;c->received=c->image_bytes=0;c->rx_high=c->rx_bits=c->tx_counter=0;memset(c->session,0,16);}
void ao_tick(struct ao_context*c,uint64_t now){if(!c||!c->initialized)return;uint32_t generation=c->port.generation(c->port.context);if(generation!=c->authority_generation){abort_session(c);c->pending=0;c->authority_generation=generation;}if(c->pending&&(now<c->query_started||now-c->query_started>=AO_CHALLENGE_MS))c->pending=0;if(!live(c)||((c->state==AO_UPLOADING||c->state==AO_VERIFIED)&&(now<c->started||now<c->last_activity||now-c->started>=AO_SESSION_MS||now-c->last_activity>=AO_IDLE_MS)))abort_session(c);}
